# ============================================================================
# 셀 3 — 첫 35 조인일 창 + MET 파싱 (기존 경로 vs 엄격 파서 비트 동일성 CT9a) + sentinel 통계
# ============================================================================
WINDOW_DAYS = 35
NONWEAR_MET = 0.5
MET_COL = "CONVERT(activity_met_1min USING utf8)"

def parse_series(s):                 # run-2/run-4 경로 (np.fromstring)
    if not isinstance(s, str):
        return np.empty(0)
    s = s.strip().strip("/")
    if not s:
        return np.empty(0)
    try:
        a = np.fromstring(s, sep="/")
        if a.size:
            return a
    except Exception:
        pass
    try:
        return np.asarray(s.split("/"), dtype=np.float64)
    except Exception:
        return np.empty(0)

def parse_strict(s):                 # 봉인 채점기용: 끝의 '/' 정확히 1개 제거 → split → 정확히 1440 개 → 전부 유한
    if not isinstance(s, str):
        raise ValueError("MET 문자열이 아님")
    t = s.strip()
    if t.endswith("/"):
        t = t[:-1]
    toks = t.split("/")
    if len(toks) != 1440:
        raise ValueError(f"MET 토큰 수 {len(toks)} != 1440")
    a = np.asarray(toks, dtype=np.float64)
    if not np.isfinite(a).all():
        raise ValueError("MET 에 비유한 값")
    return a

_t0 = time.time()
_rows_a = [parse_series(v) for v in daily[MET_COL].to_numpy()]
_len = np.array([r.size for r in _rows_a])
assert (_len >= 1440).all()
MET_A = np.stack([r[:1440] for r in _rows_a]).astype(np.float64)
_rows_b = [parse_strict(v) for v in daily[MET_COL].to_numpy()]
MET_B = np.stack(_rows_b)
_same_met = bool(np.array_equal(MET_A, MET_B)) and bool((_len == 1440).all())
CT["CT9a_strict_parser_identical"] = {"gate": True, "pass": _same_met, "n_days": int(len(daily)), "len_counts": {int(k): int(v) for k, v in pd.Series(_len).value_counts().items()}}
print(f"MET 파싱 {len(daily):,}일 {time.time()-_t0:.1f}초 | 길이 {CT['CT9a_strict_parser_identical']['len_counts']} | 엄격 파서 비트 동일: {_same_met}")
assert _same_met
MET = MET_B.astype(np.float32); del _rows_a, _rows_b, MET_A, MET_B
WORN = MET >= NONWEAR_MET; cov = WORN.mean(1)
def _longest_run(m):
    p = np.concatenate(([0], m.astype(np.int8), [0])); d = np.diff(p)
    st = np.flatnonzero(d == 1); en = np.flatnonzero(d == -1); L = en - st
    return int(L.max()) if L.size else 0
ZERO_RUN = np.array([_longest_run(z) for z in (MET == 0.0)])
daily["_rank"] = daily.groupby("sid").cumcount()
W_IDX = np.flatnonzero(daily["_rank"].to_numpy() < WINDOW_DAYS)
W = daily.iloc[W_IDX].reset_index(drop=True)
assert (W.groupby("sid").size() == WINDOW_DAYS).all()
REF_DAILY = {"days_joined": int(len(daily)), "met_coverage_median": float(np.median(cov)), "met_coverage_p1": float(np.percentile(cov, 1)),
             "days_coverage_lt_0.8": int((cov < 0.8).sum()), "days_zero_run_gt_60": int((ZERO_RUN > 60).sum()),
             "first35_days_zero_run_gt_60": int((ZERO_RUN[W_IDX] > 60).sum()), "first35_days_coverage_lt_0.8": int((cov[W_IDX] < 0.8).sum())}
print(f"창 적용 {len(W):,}행 = 174 × {WINDOW_DAYS} | 착용률 median {REF_DAILY['met_coverage_median']:.3f} p1 {REF_DAILY['met_coverage_p1']:.3f} | 0.0 sentinel run>60분 {REF_DAILY['days_zero_run_gt_60']}일 (첫 35일 창 안 {REF_DAILY['first35_days_zero_run_gt_60']}일)")
